export interface CreateGroupRequest {
  /** Leave empty and the server allocates one. */
  groupId?: string;
  name: string;
  avatar?: string;
  introduction?: string;
  type?: GroupType;
  /** The caller is added and made owner whatever this says. */
  memberIds?: string[];
  joinMode?: GroupJoinMode;
  inviteMode?: GroupInviteMode;
  maxMemberCount?: number;
  extensions?: JsonObject;
}

export interface GroupIdRequest {
  groupId: string;
}

export interface UpdateGroupRequest {
  name?: string;
  avatar?: string;
  introduction?: string;
  joinMode?: GroupJoinMode;
  inviteMode?: GroupInviteMode;
  maxMemberCount?: number;
  extensions?: JsonObject;
}

export interface UpdateGroupCommand {
  groupId: string;
  update?: UpdateGroupRequest;
}

/**
 * A cursor over one group's list — `group.memberList`, and `group.applicationList`, where an empty
 * `groupId` means "every group I manage".
 */
export interface GroupCursorRequest {
  /** Required by `group.memberList`. For `group.applicationList`, `''` lists across every group the caller manages. */
  groupId: string;
  cursor?: string | null;
  /** 1…200 is kept; anything else — absent, 0, or over 200 — becomes 50. A super group is never listed in one frame. */
  limit?: number;
}

export interface GroupMembersRequest {
  groupId: string;
  userIds: string[];
  reason?: string;
}

export interface JoinGroupRequest {
  groupId: string;
  reason?: string;
}

// ---------------------------------------------------------------------------- groups (T3)

/**
 * A request to join a group that needs approval, or an ordinary member's invitation into one — as
 * `group.applicationList` returns it.
 *
 * **Every status comes back, not only pending ones**: the server's list has no status filter. A
 * "requests awaiting you" badge has to filter on `status === ApplicationStatus.Pending` itself, or
 * it counts every request ever handled. `Expired` is declared and never produced today.
 * 列表返回所有状态，不只是待处理的：服务端没有按状态过滤。角标要自己筛 Pending。
 */
export interface GroupApplication {
  appId: string;
  groupId: string;
  /** The user who wants in. */
  applicantId: string;
  /** Set when an ordinary member invited them into a group that needs approval. */
  inviterId?: string | null;
  reason?: string | null;
  status: ApplicationStatus;
  /** The owner or admin who handled it. */
  handlerId?: string | null;
  handleReason?: string | null;
  /** Unix ms. */
  createdAt: number;
  /** Unix ms. Absent while pending. */
  handledAt?: number | null;
}

/** Body of `group.transfer`. */
export interface TransferOwnerRequest {
  groupId: string;
  /** Must already be a member (`1503` otherwise), and must not be the caller (`1001`). */
  newOwnerId: string;
}

/** Body of `group.handleApplication`. */
export interface HandleApplicationRequest {
  groupId: string;
  applicantId: string;
  /**
   * **Required here although the server does not require it: absent means reject.** The C# default
   * is `false`, so a body that forgot the field would turn somebody away without anyone deciding
   * to. The type makes the decision explicit instead.
   * 服务端省略即拒绝，所以这里设成必填：忘了写的请求会在没人决定的情况下拒掉一个人。
   */
  accept: boolean;
  /** Stored as `handleReason`. */
  reason?: string;
}

/** Body of `group.setRole`. */
export interface SetRoleRequest {
  groupId: string;
  userId: string;
  /**
   * **`GroupRole.Member` or `GroupRole.Admin`, and nothing else — by type, because the server does
   * not check.** It refuses `Owner` (`1008`, "use group.transfer") but stores any other integer it
   * is given, and two of them are privilege bugs: `0` escapes a group-wide mute (only `Member` is
   * muted), and `4` or above counts as a manager that outranks every admin. The closed type is what
   * stops that being one typo away. Omitting the field server-side means `Member`, so the property
   * is required here too — a demotion should never be the result of leaving something out.
   * 只接受 Member / Admin：服务端拒 Owner，却会原样存下其它任何整数——0 能躲过全员禁言，4 以上比管理员还大。
   */
  role: typeof GroupRole.Member | typeof GroupRole.Admin;
}

/** Body of `group.mute` — the group-wide switch. */
export interface MuteGroupRequest {
  groupId: string;
  /** **Absent means `true`.** Unmuting is `mute: false`, sent explicitly; `untilMs` is then ignored. */
  mute?: boolean;
  /**
   * Unix ms the mute lasts until. Absent with `mute: true` is indefinite.
   *
   * **Never send a time that has already passed: the server reads it as *indefinite*, not as
   * "unmute".** Its own comment says the opposite; its code sets the group muted and drops the
   * deadline. A value computed as `Date.now() + duration` is safe; one taken from an old form state
   * is not.
   * 不要发已经过去的时间：服务端把它当成「无限期」，而不是「解除」。
   */
  untilMs?: number;
}

/** Body of `group.muteMember` — one member. */
export interface MuteMemberRequest {
  groupId: string;
  userId: string;
  /**
   * Unix ms the member stays muted until. **Absent, null or in the past unmutes**; there is no
   * indefinite member mute — send a far-future time for one. Note the opposite reading from
   * {@link MuteGroupRequest.untilMs}, where a past time mutes indefinitely.
   * 缺省或过去的时间即解除；没有「无限期禁言个人」，要就发一个很远的时间。与全员禁言的读法正好相反。
   */
  untilMs?: number;
}

/** Body of `group.setNickname` — the name somebody goes by inside one group. */
export interface SetGroupNicknameRequest {
  groupId: string;
  /**
   * Whose nickname. **Absent, `''` or the caller's own id means the caller**, which any member may
   * set. Anybody else's needs owner or admin *and* outranking them (`1504` / `1511`).
   */
  userId?: string;
  /** Trimmed; absent or blank clears it. Longer than 64 characters is **silently truncated**, not refused. */
  nickname?: string;
}

/** Body of `group.announcement`. */
export interface AnnouncementRequest {
  groupId: string;
  /**
   * Trimmed; absent, null or blank clears it. Longer than 4096 characters is **silently truncated**,
   * not refused — so read the group back if the exact text matters.
   */
  announcement?: string;
}

// ---------------------------------------------------------------------------- media

export interface UploadTicketRequest {
  fileName: string;
  /** MIME type. The server refuses types the tenant has not allowed rather than accepting the upload. */
  contentType: string;
  size?: number;
}

export interface MediaUploadTicket {
  /**
   * Put **this** in the message, never `downloadUrl`. Every reader signs their own short-lived
   * link from the key, which is what makes expiry and revocation possible at all — a URL baked
   * into a message is public forever the moment it leaks.
   */
  objectKey: string;
  /** Presigned PUT. Upload goes straight to object storage, never through the gateway. */
  uploadUrl: string;
  downloadUrl: string;
  /** Present when the storage backend needs a multipart POST rather than a PUT. */
  formFields?: Record<string, string> | null;
  expiresAt: number;
}

export interface DownloadUrlRequest {
  objectKey: string;
  /** 1…86400; anything outside becomes 3600. */
  lifetimeSeconds?: number;
}

// ---------------------------------------------------------------------------- push

/**
 * Vendor channel. Aliases (`ios`, `firebase`, `hms`, …) are folded server-side; an unknown value is
 * **rejected** with the legal list rather than stored as a token nothing can route.
 *
 * Empty falls back to the platform default, which is only reliable on iOS — Android fragments
 * across five OEM channels and the server cannot guess which one a token came from (CONTRACT §6.1).
 */
export type PushProvider = 'apns' | 'fcm' | 'huawei' | 'xiaomi' | 'oppo' | 'vivo' | 'honor' | (string & {});

export interface RegisterPushTokenRequest {
  provider: PushProvider;
  token: string;
  /** BCP-47. Defaults to the socket's `lang`. */
  language?: string;
}

/**
 * Body of `push.clicked` — the tap on a notification, reported back for the delivery funnel.
 *
 * **Both fields are optional and the identity is never in the body.** The row is located from the
 * connection: a `pushId` is only believed when it points at this user's own device, and without one
 * the server takes this device's newest delivery. That is what stops a client from marking another
 * user's notification clicked, or probing which `pushId` values exist.
 *
 * `messageId` is a **string** for the reason every message id in this SDK is one: the ids exceed
 * JavaScript's exact-integer range, and a number round-trips to a different id.
 */
export interface PushClickedRequest {
  /** The delivery's `pu_…` id, when the notification payload carried one. */
  pushId?: string;
  /** The payload's `msgId`, when the tap gave you one. */
  messageId?: string;
}

// ---------------------------------------------------------------------------- moderation

/**
 * Why a report was filed. The server's vocabulary, not a hint: an unrecognised value is **rejected**
 * (`1001`, "that is not a report category") rather than folded into `other`, which would quietly
 * change what the reporter said. Unlike {@link PushProvider}, the refusal does not name the legal
 * values — take them from this union, not from the error message.
 *
 * Left open the way {@link PushProvider} is. A category the platform adds should be reachable the
 * day it ships, and a closed union would turn that into a compile error on the customer's machine
 * — which is a decision about their release schedule, not ours.
 */
export type ReportCategory =
  | 'spam'
  | 'harassment'
  | 'fraud'
  | 'pornography'
  | 'violence'
  | 'other'
  | (string & {});

/**
 * An end user reporting another.
 *
 * **There is no field for the reporter and there must not be.** It comes from the socket, which is
 * the only surface where the user id is a fact rather than a parameter; a field would let one
 * account file in another's name, which is both a way to get somebody banned and a way to poison
 * the count a moderator decides on.
 *
 * 举报人来自连接，请求体里没有这个字段：有了它，一个账号就能以另一个账号的名义举报。
 */
export interface SubmitReportRequest {
  /** Who is being reported. Reporting yourself is refused `1001`. */
  targetUserId: string;
  /** Where it happened. Optional: a report can be about an account rather than a place. */
  conversationId?: string;
  /**
   * The message being reported. **Omit it to report the account rather than one message.**
   *
   * A string, like every message id in this SDK and for the same reason — snowflake ids run past
   * JavaScript's safe-integer range, so a number cannot survive the round trip. The note at the top
   * of this file has the measurement.
   */
  messageId?: string;
  /** Defaults to `other` server-side, so a reporting UI without a picker still files something. */
  category?: ReportCategory;
  /** What the reporter typed. Usually the most useful field on the row a moderator ends up reading. */
  note?: string;
}

/**
 * A receipt, not the row.
 *
 * The reporter has no business reading back the moderation state of their own report, and the row
 * carries fields — who handled it, what they did — that are internal. Two fields is the whole
 * answer: enough to say "filed at 14:03, reference rp_…" in the UI and in a support conversation.
 */
export interface ReportReceipt {
  /** `rp_…`. Quote it when a customer asks what happened to a specific report. */
  reportId: string;
  /** Server clock, unix ms. */
  createdAt: number;
}
// ---------------------------------------------------------------------------- desk (T4)

/**
 * A customer asking for a person. **Every field is optional and the body may be omitted entirely** —
 * the server reads `null` as an empty request — so the plain "talk to a human" button is
 * `im.desk.request()`.
 *
 * Idempotent by the server's design, not by the caller's discipline: a customer who already has a
 * session in flight — queued, assigned, or still with the bot — gets that same session back rather
 * than a second one. The client most likely to call this twice is the one whose first call timed
 * out after it had already succeeded.
 * 幂等由服务端保证：最可能重复调用的，正是「超时但其实已经成功」的那个客户端。
 */
export interface DeskRequest {
  /** Routing hint the tenant queues on: product line, language, VIP tier. */
  skill?: string;
  /** Higher goes first. Used sparingly — a queue where everything is urgent has no order. */
  priority?: number;
  /**
   * Opaque context the agent's workbench renders: order id, the page they were on, a prior ticket.
   *
   * The engine copies out the keys it recognises ({@link DeskContextKeys}) and leaves everything
   * else here untouched, so a tenant's own keys travel to the workbench without a schema change.
   */
  context?: JsonObject;
}

/** One "customer asked, agent answered" pair inside a session, unix ms on both sides. */
export interface DeskResponseSample {
  customerAt: number;
  agentAt: number;
  /** Who answered, so a per-agent response time can be built from the same rows. */
  agentId?: string | null;
}

/**
 * The model-written handover summary a receiving agent reads before saying hello.
 *
 * All five members are always present when the summary itself is — a session with no summary has
 * `summary` absent rather than an empty card. `model` is here because a summary is a claim and
 * claims carry authorship.
 */
export interface DeskSessionSummary {
  /** What the customer came about. */
  issue: string;
  /** Where the conversation stands. */
  state: string;
  /** What the next agent should do first. */
  nextStep: string;
  generatedAt: number;
  /** Which provider and model wrote it. */
  model: string;
}

/**
 * One desk session, as `desk.request`, `desk.accept` and every session-level `evt.desk` frame
 * return it.
 *
 * **The last thirteen fields are the customer-service product's and were added after the engine
 * shipped** (SPEC-06 §14.1, §13.2), so a session opened before they existed has no element for any
 * of them and reads back as the default: absent, `[]`, or `false`. A build of the server that
 * predates them omits them altogether. They are therefore optional here even though a current
 * server writes `tags: []`, `ratingTags: []`, `responseSamples: []` and `star: false` out — the
 * type has to describe both servers, and `?? []` at the edge is the whole of the difference.
 *
 * 最后十三个字段是产品后加的：更早开出的会话根本没有这些元素，读回来就是默认值。
 * 所以它们在这里是可选的——尽管当前服务端会把空数组和 false 写出来，类型要同时描述两种服务端。
 */
export interface DeskSession {
  sessionId: string;
  appId: string;
  /** The IM user asking for help. A minted visitor's id is `v_…`; see {@link DeskSession.visitorId}. */
  customerId: string;
  /** The agent holding it. Absent while queued, and absent again after a release. */
  agentId?: string | null;
  /**
   * The ordinary single chat between the customer and the desk account. Everything either side
   * says is a normal message in it, sent with `msg.send` — these fields only move the *assignment*
   * around that conversation.
   */
  conversationId: string;
  state: DeskSessionState;
  skill?: string | null;
  priority: number;
  /** Unix ms. Preserved across a requeue, which is what keeps a transferred customer's place. */
  queuedAt: number;
  assignedAt?: number | null;
  closedAt?: number | null;
  /** Free-text outcome the closing agent typed. Predates the structured {@link DeskSession.disposition}. */
  resolution?: string | null;
  context?: JsonObject | null;
  /** Agents who held it before, so a transfer chain is auditable. `[]` on a session nobody has held. */
  history?: string[];
  /** When the first agent message reached the customer, unix ms. Absent while no agent has spoken. */
  firstAgentMessageAt?: number | null;
  /** 1–5, absent until (and unless) the customer rates. */
  rating?: number | null;
  /**
   * When the 1807 invitation actually went out, unix ms.
   *
   * **This is the CSAT participation denominator** (SPEC-06 §10.1), and it is stored rather than
   * derived because every reason an invitation was withheld expires long before a report runs.
   * Counting closed sessions instead prices the rate against a denominator several times too
   * large and draws a healthy desk as an ignored one.
   * 这是参评率的分母，且是存下来的而不是推导的：拿「已关闭会话」当分母会把一个健康的客服台画成没人理。
   */
  ratingInvitedAt?: number | null;
  ratingComment?: string | null;
  ratedAt?: number | null;
  summary?: DeskSessionSummary | null;

  // ---- the customer-service product's fields ------------------------------------------------

  /** Labels the closing agent chose. Two-level paths as the centre configured them. */
  tags?: string[];
  /** How the visitor arrived: `web`, `app`, `api`, and the WeChat kinds. */
  channel?: string | null;
  /** The product's visitor record behind {@link DeskSession.customerId}, when the customer is a minted visitor. */
  visitorId?: string | null;
  /** The centre this session belongs to. Absent for a session opened before centres existed. */
  deskId?: string | null;
  /** The skill group it was routed to — the product's id for what the engine routes on as `skill`. */
  groupId?: string | null;
  disposition?: DeskDisposition | null;
  /** Why it ended. A **string** on the wire, unlike `state`. Absent while it is open. */
  endReason?: DeskEndReason | null;
  /** The 1–2 star tags joined — the "why" behind a bad score. Absent for a good or untagged one. */
  ratingReason?: string | null;
  /** The customer's answer to "was your problem solved". Absent until rated, and absent when the survey did not ask. */
  ratingResolved?: boolean | null;
  /** Every per-star tag the customer picked, whatever the score. */
  ratingTags?: string[];
  /** Starred by the holding agent for their own list. */
  star?: boolean;
  /** Unix ms until which the session is snoozed. */
  snoozedUntil?: number | null;
  /** One sample per customer message that got a reply, for the average response time. */
  responseSamples?: DeskResponseSample[];
}

/**
 * Which session to take. **Omit the id — and the whole body — to take the next one waiting**, which
 * is the normal case: agents pull, nothing is ever pushed at them. Naming an id is a supervisor or
 * an agent picking a specific customer out of the queue.
 *
 * An empty queue answers `1002 NotFound`, not an empty success.
 */
export interface DeskAcceptRequest {
  sessionId?: string;
}

/** What both halves of a transfer carry, whichever of the three targets is named. */
export interface DeskTransferBase {
  sessionId: string;
  /**
   * Handover note for the receiving agent. **Internal**: it is filed as a note and never enters the
   * customer-visible 1803 line, so it can say what an agent would not say to the customer.
   */
  note?: string;
}

/**
 * Hands a session on, carrying its whole history with it (SPEC-06 §4.4).
 *
 * **Exactly one of the three targets, enforced by the type rather than by a round trip.** The
 * server checks the same thing and answers `1001 "exactly one of toAgentId, toSkill or toQueue is
 * required"`; expressing it as a union means a workbench that names two — or none — does not
 * compile, instead of failing in front of a customer mid-handover. That is also why the two
 * unusable members are `never` in each branch rather than merely absent: an object literal built by
 * spreading a form's state would otherwise satisfy the branch it half-matches.
 *
 * The cost is real and worth naming: a `toQueue: boolean` held in a variable does not type-check,
 * because "maybe the queue" is not a target. Branch at the call site, which is where the agent's
 * three radio buttons already branch.
 *
 * 三个目标里恰好一个，由类型而不是由一次往返来保证：多写一个或一个不写都编译不过，
 * 而不是在交接到一半时当着客户的面失败。代价是不能用一个 boolean 变量表达 toQueue——
 * 「也许是队列」不是一个目标。
 */
export type DeskTransferRequest =
  | (DeskTransferBase & {
      /** A named agent, who must be available and under capacity. */
      toAgentId: string;
      toSkill?: never;
      toQueue?: false;
    })
  | (DeskTransferBase & {
      /** A skill queue; the session goes to the front of it with its original `queuedAt` stamp. */
      toSkill: string;
      toAgentId?: never;
      toQueue?: false;
    })
  | (DeskTransferBase & {
      /** Back to the queue it came from, same stamp, same position — the 1805 requeue, chosen by a person. */
      toQueue: true;
      toAgentId?: never;
      toSkill?: never;
    });

/**
 * The end-of-session drawer (SPEC-06 §4.9). Every field but the id is optional, and **an omitted
 * field is not the same as a field set to null**: the server writes nulls out of its own JSON, so
 * it reads "absent" as "the agent did not fill this in".
 *
 * **`inviteRating` omitted means `true`.** It is a C# property initialiser, not a nullable, so the
 * only way to close without asking for a rating is to send `inviteRating: false` explicitly.
 * Passing `undefined` still invites.
 * 省略 inviteRating 等于 true：只有显式发 false 才是「不邀评」。
 */
export interface DeskCloseRequest {
  sessionId: string;
  /** Free-text outcome, kept on the record for whoever reads it later. */
  resolution?: string;
  /** At most 20, each at most 64 characters; over either and the whole call is `1001`. */
  tags?: string[];
  disposition?: DeskDisposition;
  /** The agent-edited summary, filed as a note. Never shown to the customer. */
  summary?: string;
  /** Defaults to true when absent. The engine's own anti-noise rules still apply on top. */
  inviteRating?: boolean;
}

/**
 * Availability, and — by the same call — the heartbeat that proves this workbench is still there.
 *
 * The two are one message on purpose: an agent listed as available whose console stopped talking to
 * the server is exactly the state that leaves a customer waiting on somebody who went home, so
 * there is no way to express it.
 */
export interface DeskStatusRequest {
  /** A number on the wire. Anything outside 0–3 is `1001 "unknown agent status '<n>'"`. */
  status: AgentStatus;
  /** Sessions this agent will hold at once. Absent keeps the deployment default; the server clamps it. */
  maxConcurrent?: number;
}

/**
 * The customer's answer to the rating survey (SPEC-06 §4.9), sent in reply to the 1807 notice.
 *
 * Absent is meaningful on all three optional members and is not the same as a falsy value:
 * `resolved` absent means the survey did not ask, and an absent `starTags` is "no tags offered"
 * rather than "none picked".
 */
export interface DeskRateRequest {
  sessionId: string;
  /** 1–5. Anything else is `1001`. */
  score: number;
  /** "Was your problem solved" — the only customer-side evidence of first-contact resolution. */
  resolved?: boolean;
  /** At most 12, each at most 64 characters. With a 1–2 star score these are the reason behind it. */
  starTags?: string[];
  /** At most 2000 characters. */
  comment?: string;
}

/** Body of `desk.suggest`: the session this agent holds. */
export interface DeskSuggestRequest {
  sessionId: string;
}

/**
 * Which canned replies to list. All three are filters; omitting all three lists the whole centre's
 * phrasebook, **including every member's `personal` entries** — see `ownerMemberId`.
 */
export interface DeskCannedRequest {
  skill?: string;
  /** One tier only. An unrecognised value is `1001`. */
  scope?: DeskCannedReplyScope;
  /**
   * Whose personal entries to include. **A filter, not a guard: the server does not narrow this to
   * the caller.** Absent means "do not filter by owner", which returns everyone's `personal`
   * entries, and a value belonging to somebody else returns theirs. Pass your own member id to get
   * "shared, plus mine". Only `/console/v1/desks/{deskId}/canned-replies` rewrites the owner to
   * the caller.
   * 过滤参数而非权限：服务端不按调用方收窄，省略即返回所有人的 personal 条目。
   */
  ownerMemberId?: string;
}

/** One canned reply an agent pastes instead of retyping the same answer. At most 200 per tenant. */
export interface DeskCannedReply {
  /** Store-assigned; empty string on create. */
  id: string;
  /** At most 100 characters. */
  title: string;
  /** At most 4000 characters. */
  content: string;
  /** Absent means every agent sees it. */
  skill?: string | null;
  /** Never absent: an entry stored before the field existed reads back as `all`. */
  scope: DeskCannedReplyScope;
  /** The folder the workbench files it under. Absent is the root. */
  folder?: string | null;
  /** Required for a `personal` entry — without it the write is `1001`. Absent for the other two tiers. */
  ownerMemberId?: string | null;
  updatedAt: number;
}

/** The queue as a supervisor watches it. */
export interface DeskQueueView {
  waiting: number;
  assigned: number;
  availableAgents: number;
  /** Seconds the head of the queue has been waiting — the number a supervisor actually watches. */
  headWaitSeconds: number;
  /**
   * Average seconds from entering the queue to the first agent message, over the last 24 hours.
   *
   * **Absent means "nothing measurable in the window", and a dashboard must draw it that way.**
   * Drawing a 0 says "instant answers", which is the opposite of what an empty window means.
   * 缺席表示「窗口内没有可测样本」，要画成「暂无数据」——画 0 就成了「秒回」。
   */
  avgFirstResponseSeconds?: number | null;
  waitingBySkill: Record<string, number>;
}

/**
 * One agent as the roster sees them right now.
 *
 * A console that has stopped heart-beating is still listed: `lastSeenAt` is what makes it stale,
 * and hiding the row would hide the fact that somebody's workbench died holding sessions.
 */
export interface DeskAgentView {
  agentId: string;
  status: AgentStatus;
  /** Declared capacity: how many concurrent sessions this agent accepts. */
  maxConcurrent: number;
  /** Counted from the live set, never a stored counter. */
  activeSessions: number;
  /** Last heartbeat, unix ms. Stale with a non-offline status means they dropped without saying goodbye. */
  lastSeenAt: number;
}

/**
 * One waiting visitor's place in the line, from the widget surface (SPEC-06 §14.3).
 *
 * **`position` and `minutes` are both "not measured" when absent, never zero.** A session that is
 * no longer queued answers with both absent and `queued: false`, which is how a plugin knows to
 * stop asking rather than to render a 0.
 */
export interface DeskQueuePosition {
  sessionId: string;
  queued: boolean;
  /** 1-based place in its own skill queue. */
  position?: number | null;
  /** A rough wait, present only when there is something real to derive it from. */
  minutes?: number | null;
  /** How long this visitor has already waited, seconds. Always measurable. */
  waitedSeconds: number;
}

/** One knowledge-base article. The embedding never leaves the server. */
export interface KbArticle {
  /** Store-assigned; empty string on create. */
  id: string;
  /** At most 200 characters. */
  title: string;
  /** At most 20000 characters. */
  body: string;
  /** At most 20. `[]` rather than absent on an article this build wrote. */
  tags?: string[];
  /**
   * **Read-only, and the server computes it**: `vector` when the stored embedding matches the
   * tenant's current provider and model, `keyword` otherwise — including when no LLM is configured
   * at all. Sending a value here does not change it; it is rendered so a tenant can see which
   * articles need re-embedding after switching models.
   */
  retrieval?: string;
  /** The help-centre category. Absent is uncategorised. */
  category?: string | null;
  /** A draft is kept but grounds nothing. An article stored before the field existed reads as published. */
  state?: KbArticleState;
  /** Other phrasings of the question this answers: at most 20, each at most 200 characters. */
  similarQuestions?: string[];
  /** Pinned to the top of the help centre and the widget's first screen. */
  featured?: boolean;
  updatedAt: number;
}

/** Who wrote a note, as the frame announcing it carries them. */
export interface DeskNoteAuthor {
  memberId: string;
  name?: string | null;
  avatar?: string | null;
}

/**
 * One internal note on a session: an agent's remark, a handover text, the model's summary, or a
 * supervisor's whisper. **None of it is ever shown to the customer.**
 */
export interface DeskNote {
  noteId: string;
  deskId: string;
  appId: string;
  sessionId: string;
  /** The transcript it belongs to, when known — lets a timeline join without a second read. */
  conversationId?: string | null;
  /** The member who wrote it. Absent for a note the engine or the model authored. */
  authorMemberId?: string | null;
  kind: DeskNoteKind;
  body: string;
  /** Members addressed with `@`. Each is told, and the workbench's "@me" group counts them. */
  mentions?: string[];
  /** Unix ms. */
  at: number;
}

// ---------------------------------------------------------------------------- room (T4)

/**
 * The body `room.join`, `room.quit` and `room.onlineCount` take.
 *
 * Rooms are created by the tenant's own backend (`POST /v1/rooms`) and never from the socket, so the
 * id is always one the application was handed — there is no `room.create` here and there will not
 * be one: a room is a broadcast surface the tenant owns, not something an end user opens.
 * 房间只能由租户后端经 POST /v1/rooms 创建，套接字上没有 room.create：房间是租户拥有的广播面。
 */
export interface RoomIdRequest {
  roomId: string;
}

/**
 * The body `room.memberList` takes. The server clamps `limit` to 1…100 and reads anything else —
 * including absent — as 50.
 */
export interface RoomCursorRequest {
  roomId: string;
  /** Opaque; pass back the previous page's `nextCursor` verbatim. Absent for the first page. */
  cursor?: string;
  limit?: number;
}

/**
 * The message half of a `room.send`, as the server reads it.
 *
 * **Narrower than {@link SendMessageRequest}, on purpose.** The room is the target, so there is no
 * `conversationId` / `receiverId` / `groupId`; a room message is never stored, so there is nothing
 * to quote or thread under; and of the options only `priority` means anything — a room sheds
 * `Low` first when it is over its rate, which is how a gift storm stays out of the host's way.
 * Everything else the server would bind and then ignore, and a field that is accepted and ignored
 * is a field somebody will rely on.
 *
 * These keys travel **nested**, and a nested object is bound by member name exactly as spelled here
 * (CONTRACT §2): a hand-written `ClientMsgId` is dropped without a word, and the send then fails
 * `1001` for a field that looks present.
 * 这些键是嵌套在 message 里的，服务端按名字精确匹配：手写成 ClientMsgId 会被静默丢掉，然后以 1001 失败。
 */
export interface RoomMessage {
  /**
   * Idempotency key, required by the server (`1001` without one). Optional here because
   * `room.send` generates one when it is absent, exactly as `msg.send` does.
   */
  clientMsgId?: string;
  /** Defaults to `MessageContentType.Text`. */
  contentType?: MessageContentType;
  content: JsonObject;
  mentionAll?: boolean;
  mentionedUserIds?: string[];
  /** Only `priority` is read on a room. `Low` is shed first when the room is over its rate. */
  options?: Pick<MessageOptions, 'priority'>;
  /** Client clock, unix ms. Filled in when absent; the server stamps `createTime` itself. */
  sendTime?: number;
  extensions?: JsonObject;
}

/** The body `room.send` takes. */
export interface RoomSendRequest {
  roomId: string;
  message: RoomMessage;
}

/**
 * The body `room.mute` takes. **One call is both mute and unmute, and which one is decided by
 * `untilMs`:** a moment in the future mutes until then; absent, or a moment already past, unmutes.
 *
 * `userId` picks the scope: absent mutes the whole room (the owner and admins still speak — that is
 * what a room-wide mute is for), present mutes that one member. Only the owner or an admin may call
 * it (`1103`), and the owner cannot be muted (`1511`).
 * untilMs 决定是禁言还是解禁：将来的时刻＝禁言到那时，缺席或已过去＝解禁。userId 缺席＝全房禁言。
 */
export interface RoomMuteRequest {
  roomId: string;
  userId?: string;
  /** Unix ms. Absent or past means unmute. */
  untilMs?: number;
}

/** The body `room.kick` takes. Owner or admin only (`1103`); the owner cannot be kicked (`1511`). */
export interface RoomKickRequest {
  roomId: string;
  userId: string;
}

/** A chat room, as `room.join` describes it. */
export interface ChatRoom {
  appId: string;
  roomId: string;
  name: string;
  avatar?: string | null;
  ownerId: string;
  /** Who besides the owner may mute and kick. Set by the tenant backend; not editable from the socket. */
  admins: string[];
  /** `0` means unlimited. A join past it is `1601 RoomFull`. */
  maxOnline: number;
  /** How many recent messages a joiner is handed in {@link RoomJoinResult.recent}. `0` disables it. */
  historyBufferSize: number;
  /** Messages per second the room as a whole accepts before shedding `Low` priority. */
  rateLimitPerSecond: number;
  muteAll: boolean;
  destroyed: boolean;
  /** Unix ms. */
  createdAt: number;
  extensions?: JsonObject | null;
}

/**
 * What `room.join` answers.
 *
 * `recent` is the room's ring buffer, oldest first — **a courtesy for whoever just walked in, not a
 * history**. Every message in it carries `seq: 0`, nothing can be paged behind it, and it never
 * reaches `onMessage` or a cursor: it is returned to the caller and that is all.
 * recent 是房间的环形缓冲，给刚进来的人看的，不是历史：seq 恒为 0，翻不了页，也不进 onMessage 与游标。
 */
export interface RoomJoinResult {
  room: ChatRoom;
  onlineCount: number;
  recent: ImMessage[];
}

// ---------------------------------------------------------------------------- msg.stream* (T4)

/**
 * The body `msg.streamBegin` takes: open a reply that will be typed out a fragment at a time.
 *
 * **A stream is ephemeral until it completes.** Its fragments go to the online members of the
 * conversation only, on `evt.stream`, and are never stored; `msg.streamComplete` turns what was
 * appended into **one ordinary message with a real seq**, sent through the same path as `msg.send`.
 * Who may stream is who may send: any signed-in user, bot or desk agent, as itself only, into a
 * single chat (self-chat included) or a group — the same refusals as `msg.send` apply here, at begin
 * (`1104` banned, `1408` muted, `1303` blocked, `1302` not a friend, `1500` / `1501` / `1503` / `1506`
 * / `1505` for groups), plus `1008` for a chat room, a system or assistant conversation, or an
 * audience above 200, and `1003` above 60 begins a minute per user. No app setting or add-on gates
 * it.
 *
 * 流在收尾之前是短暂的：分片只推给会话里在线的人、从不落库；streamComplete 把追加的内容变成一条
 * 有真实 seq 的普通消息，走 msg.send 同一条路。谁能发消息谁就能开流，只能以自己的身份，
 * 只限单聊（含自聊）与群；msg.send 的拒绝在开流时就判。
 */
export interface BeginStreamRequest {
  /** One of `conversationId`, `receiverId` or `groupId`, read in that order. None of them is `1001`. */
  conversationId?: string;
  receiverId?: string;
  groupId?: string;
  /**
   * The idempotency key of the message this stream becomes. **Required, and not filled in for you**,
   * unlike `msg.send`: the reply does not echo it, and it is the one handle you keep on the finished
   * message — when the server refuses the completed text (moderation, a tenant webhook), re-sending
   * it with `msg.send` under this same key yields the one message rather than a second. Blank is
   * `1001`.
   * 最终消息的幂等键，必填且不替你生成：答复里不回显它，而收尾被拒之后用同一个键经 msg.send 重发，
   * 才得到同一条消息而不是第二条。
   */
  clientMsgId: string;
  /**
   * The content type of the finished message, sent as an integer. Absent means `Text`. The final
   * message carries the type you open with; `MessageContentType.Stream` is not used by the server.
   */
  contentType?: MessageContentType;
  /**
   * Whatever a client should draw while the stream runs — an assistant's name, an avatar. Echoed only
   * in the opening `evt.stream` frame; it is not part of the finished message.
   */
  placeholder?: JsonObject;
  /**
   * The finished message's options, nested and bound by name exactly as spelled (a misspelled key is
   * dropped without a word). Checked at begin: a client may not set `pushConfig.title` / `body`
   * (`1103`), nor stream unstored media while the app moderates (`1103`).
   */
  options?: MessageOptions;
  /** Merged into the finished message; keys given at completion win. */
  extensions?: JsonObject;
}

/**
 * What `msg.streamBegin` answers. Keep `streamId`: every later call names it, and only the user who
 * opened the stream may use it (`1103` for anyone else).
 */
export interface StreamHandle {
  /** `st_…`, at most 64 characters of `[A-Za-z0-9_-]`. */
  streamId: string;
  /** The conversation the stream resolved to — and the one the finished message lands in. */
  conversationId: string;
  /** Unix ms. Also the finished message's `sendTime`: a reply sits where it started, not where it ended. */
  startedAt: number;
  /**
   * Seconds without an append after which the server abandons the stream (30 by default). It is
   * reaped up to one sweep later — 30 to 60 s after the last begin or append — with a terminal
   * `evt.stream` frame and no message. There is no limit on total duration, only on silence.
   */
  idleTimeoutSeconds: number;
}

/**
 * The body `msg.streamAppend` takes: the next fragment.
 *
 * At most 4096 characters per fragment, and the accumulated text is capped (16384 characters, or
 * less on an app with a small message limit) — both are `1401`, **and the stream stays open**: what
 * was appended so far can still be completed. 100 appends a second per stream (`1003`). An empty
 * `delta` is answered with success and does nothing — no frame, no rate token.
 * 每片最多 4096 字符，累计有上限，超了都是 1401 且流仍然开着——已有的内容照样可以收尾。
 */
export interface StreamAppendRequest {
  streamId: string;
  delta: string;
}

/**
 * The body `msg.streamComplete` takes. Answers the stored message's {@link SendMessageResult}, and
 * may fail with anything `msg.send` can (moderation, a webhook, a store that is down) — **the stream
 * is consumed either way**, and the audience gets a terminal frame with `abortReason` instead of a
 * message. A second complete or an abort after one is `1002`.
 */
export interface CompleteStreamRequest {
  streamId: string;
  /**
   * Absent or empty: the finished message's content is `{ text: <every delta joined in order> }`.
   * Given: it **replaces** the appended text outright — a producer can send a cleaned-up version of
   * what it streamed.
   */
  content?: JsonObject;
  /** Merged over the extensions given at begin; these keys win. */
  extensions?: JsonObject;
}

/**
 * The body `msg.streamAbort` takes: end the stream with no message — the generator failed, or the
 * user pressed stop. Worth calling rather than leaving to the idle sweep: the placeholder clears now
 * instead of after up to a minute. A second abort, or one after complete, is `1002`.
 */
export interface StreamAbortRequest {
  streamId: string;
  /** Shown to the audience in place of the message. Blank becomes "aborted by the producer"; cut to 256 characters. */
  reason?: string;
}

// ---------------------------------------------------------------------------- msg.schedule*, conv folders, msg.translate (T4)

/**
 * The body `msg.schedule` takes: a message to send later — the addressing and payload of
 * {@link SendMessageRequest} with `sendAt` beside them.
 *
 * **Flat, and narrower than `SendMessageRequest`, on purpose.** The server binds exactly these
 * thirteen members at the top level (not `{ sendAt, message: { … } }`). There is no `options`: the
 * scheduler refuses online-only and non-persistent sends anyway, and the rest of the options are a
 * nested object this socket would drop without a word — a field accepted and ignored is a field
 * somebody relies on. There is no `sendTime` either: the message is stamped when it is sent.
 * 扁平，且比 SendMessageRequest 窄：服务端在顶层绑定这十三个成员。没有 options（定时发送本就拒绝仅在线/不入库，
 * 其余部分是会被静默丢掉的嵌套对象），也没有 sendTime（发出时才盖时间）。
 *
 * **It is not a message until it is sent**: no seq, no history, nothing on the recipient's side.
 * When it fires the recipient gets an ordinary `evt.message` with a normal seq, through the same send
 * path — and the same refusals, decided again at that moment. No event announces creating, cancelling
 * or firing a schedule; another device of the sender re-reads `msg.scheduled`.
 * 发出之前它不是消息：不占 seq、不进历史、对方看不到。到点后接收方收到一条普通的 evt.message。
 * 创建、取消、发出都没有事件，发送者的其它设备要重新读 msg.scheduled。
 *
 * The body goes out exactly as given; the SDK fills nothing in.
 */
export interface ScheduleRequest {
  /**
   * When to send, unix ms. At least `MinScheduleLeadSeconds` (10 s) from now and at most
   * `ScheduleHorizonDays` (90 days) ahead — both `1001` otherwise, and both deployment options
   * (`IM:Extras`). The dispatcher sweeps every 15 s, so a message goes out on the first sweep at or
   * after `sendAt`: up to about 15 s late, never early.
   * 至少 10 秒之后、至多 90 天之内，否则 1001。派发每 15 秒扫一次，所以消息在 sendAt 之后的第一次扫描发出：
   * 最多晚约 15 秒，从不提前。
   */
  sendAt: number;
  /** One of `conversationId`, `groupId` or `receiverId`, read in that order. None of them is `1001`. */
  conversationId?: string;
  receiverId?: string;
  groupId?: string;
  /** Bound and stored, but not used to address the message — the id fields above do that. */
  conversationType?: ConversationType;
  /**
   * The idempotency key of the eventual send. **Optional, and not generated here**: left empty, the
   * server derives `sch-<scheduleId>`. It deduplicates the *send*, not the schedule — `msg.schedule`
   * itself is not idempotent, so a retry after a lost reply queues a second schedule (with the same
   * key given, the second one collapses into the first message when it fires).
   * 最终发送的幂等键，可省略且不替你生成：留空时服务端派生 sch-<scheduleId>。它去重的是发送而不是定时——
   * msg.schedule 本身不幂等，丢了答复再重试会排进第二条定时。
   */
  clientMsgId?: string;
  /** Sent as an integer. Absent means `Text`. */
  contentType?: MessageContentType;
  /** Required and non-empty: an empty object is `1001` "content is required". */
  content: JsonObject;
  mentionAll?: boolean;
  mentionedUserIds?: string[];
  /** A message id, as a string. */
  quoteMessageId?: string;
  /** A message id, as a string. */
  threadRootId?: string;
  extensions?: JsonObject;
}

/**
 * One entry of the caller's outbox, as `msg.schedule` answers and `msg.scheduled` lists it.
 *
 * **There is no state field; read it from `messageId` and `error`:**
 * - neither present — still waiting (or being sent right now);
 * - `messageId` present — sent, and this is the stored message's id;
 * - `error` present — settled without a message: `"cancelled by sender"` after
 *   `msg.cancelScheduled`, otherwise the reason the send failed (`"send failed"` when there is none).
 *
 * Settled entries — sent, failed and cancelled — stay listed for about 48 hours
 * (`SettledScheduleRetentionHours`) and then disappear.
 * 没有状态字段：两者都没有＝还在等（或正在发）；有 messageId＝已发出；有 error＝没有发出，
 * 取消时是 "cancelled by sender"，否则是失败原因。已了结的条目约保留 48 小时。
 */
export interface ScheduledMessage {
  /** Keep it: `msg.cancelScheduled` takes it. */
  scheduleId: string;
  appId: string;
  senderId: string;
  /** The conversation the address resolved to at scheduling time. */
  conversationId: string;
  /** Unix ms, as requested. */
  sendAt: number;
  /** Unix ms. */
  createdAt: number;
  /** Set once sent: the stored message's id, as a string. */
  messageId?: string;
  /** Set when it settled without a message — see the type's note. */
  error?: string;
}

/** The body `msg.cancelScheduled` takes. */
export interface ScheduleIdRequest {
  scheduleId: string;
}

/**
 * A conversation folder, as `conv.folders` lists it and `conv.upsertFolder` answers it.
 *
 * **A folder holds tags, not conversations.** Filing a conversation is tagging it (`conv.setting`,
 * `setting.tags`); a folder names a set of tags and the client filters its conversation list with
 * them — so a folder can never disagree with the list it describes, and deleting one removes a name
 * and nothing else. No event announces a change; other devices re-read `conv.folders`.
 * 文件夹装的是标签不是会话：归档就是给会话打标签，文件夹只是对会话列表的筛选，删掉它只删掉一个名字。
 */
export interface ConversationFolder {
  folderId: string;
  name: string;
  /** Display order. `conv.folders` already sorts by this, then by name (ordinal). */
  order: number;
  /** Conversations carrying any of these tags belong to the folder. */
  tags: string[];
  /** Show only conversations with unread messages. */
  unreadOnly: boolean;
  /** Conversation types the folder shows, as integers. **Absent means all of them.** */
  types?: ConversationType[];
}

/**
 * The body `conv.upsertFolder` takes: create a folder (no `folderId`) or **replace** one by id.
 *
 * **A replace, not a patch.** Every member is written from this body, so a field left out is reset —
 * `tags` to none, `unreadOnly` to false, `order` to 0, `types` to all. To rename, send the whole folder
 * back with the new name. Without a `folderId` the server mints one, so a retry after a lost reply
 * creates a second folder; pass your own id to make the save repeatable.
 * 是替换不是补丁：省略的字段会被重置。改名要把整个文件夹带上新名字发回来。不带 folderId 时服务端分配新 id，
 * 丢了答复再重试会多出一个文件夹；自己给 id 才能安全重试。
 *
 * Refusals: `1001` for a blank name, a malformed id, more than 16 tags, or a tag none of the caller's
 * conversations carries yet (tag a conversation first); `1006` at 20 folders. Limits are deployment
 * options (`IM:Extras`).
 */
export interface UpsertFolderRequest {
  /** Absent or empty creates; otherwise 1–64 characters of letters, digits, `-`, `_` or `.`. */
  folderId?: string;
  /** Required, not blank; trimmed, and cut to 64 characters. */
  name: string;
  /** Negative is stored as 0. */
  order?: number;
  /**
   * At most 16, each trimmed and cut to 64 characters, duplicates dropped. Every one must already be on
   * at least one of the caller's conversations.
   */
  tags?: string[];
  unreadOnly?: boolean;
  /** Sent as integers. Absent or empty means all types (stored as absent). */
  types?: ConversationType[];
}

/** The body `conv.deleteFolder` takes. Only the name goes; the conversations keep their tags. */
export interface FolderIdRequest {
  folderId: string;
}

/**
 * The body `msg.translate` takes: translate messages the caller can already read, into one language.
 *
 * **Gated twice, and either refusal is an ordinary `ImError`:** `1204 PlanExpired` when the app's plan
 * does not include the translation add-on (Enterprise and up, or a trial), then `1203
 * FeatureNotEnabled` when it does but the deployment has no translation provider configured. Both are
 * answered before the request is looked at. Neither is latched by the SDK — a tenant can change both
 * at runtime.
 * 两道闸：套餐不含翻译增值项回 1204，含但部署没配翻译服务回 1203。两者都先于参数校验，都是普通的 ImError。
 */
export interface TranslateRequest {
  conversationId: string;
  /**
   * Message ids, as strings. At most 50 (`MaxMessagesPerRequest`); duplicates and unreadable ids are
   * dropped, and nothing left is `1001`.
   */
  messageIds: string[];
  /** BCP-47, e.g. `"zh-CN"`, `"en"`, `"ja"`. A malformed tag is `1001`. */
  targetLanguage: string;
  /** BCP-47 hint. Absent lets the provider detect it. */
  sourceLanguage?: string;
}

/**
 * What `msg.translate` answers. **Per-message failures ride inside `items`**, with the call itself
 * succeeding: one item per distinct id, in the order given, each with `text` or `error`. The whole call
 * fails only when nothing at all could be translated (a quota or provider failure with no text in hand).
 * 单条失败放在 items 里、整个调用照样成功；只有一条译文都拿不到时整个调用才失败。
 */
export interface TranslationResult {
  /** The target language as the server normalised it. */
  targetLanguage: string;
  items: TranslatedMessage[];
}

/** One message of a {@link TranslationResult}. */
export interface TranslatedMessage {
  /** A message id, as a string. Match items on it. */
  messageId: string;
  /** The translation. Absent when `error` is set. */
  text?: string;
  /** Served from cache rather than a provider call. */
  cached: boolean;
  /**
   * Why this one message was not translated — `"message not found"` (also for one the caller may not
   * see), `"message was recalled"`, no text in it, too long, or a quota or provider failure.
   */
  error?: string;
}
